SharingAsyncWaiter::SharingAsyncWaiter(
    Sharing* proxy) : proxy_(proxy) {}

SharingAsyncWaiter::~SharingAsyncWaiter() = default;

void SharingAsyncWaiter::ShutDown(
    ) {
  base::RunLoop loop;
  proxy_->ShutDown(
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}








